                  `,dependencies:[],nestedTestListUUIDs:[]}},level:"element",isNoTest:!1,noTest:""}},modifiedSfr:!1,additionalSfr:!1,consistencyRationale:"",notNew:null,xPathDetails:{},compUUID:"43259825-469e-44dc-992d-a2a2f606b40e"},"FTA_TAB.1":{title:"Default TOE access banners",cc_id:"FTA_TAB.1",iteration_id:"",xml_id:"",definition:"",optional:!0,objective:!1,selectionBased:!1,selections:{components:[],elements:[],selections:[]},useCaseBased:!1,useCases:[],implementationDependent:!1,reasons:[],tableOpen:!1,objectives:[],extendedComponentDefinition:{audit:"",componentLeveling:"",dependencies:"",managementFunction:"",toggle:!1},auditEvents:{"218228c9-cecb-4a4e-b801-304d11645afd":{items:[],optional:!1}},open:!1,elements:{"264d443d-7c4f-460e-b000-7e210b5d82fc":{elementXMLID:"fel-banner",selectableGroups:{},title:[{description:`
